#!/usr/bin/env python3
"""Keep AGENTS.md the single source of truth for agent instructions.

Every directory that carries an `AGENTS.md` must also carry a `CLAUDE.md` that
is nothing more than a pointer to it. Claude Code appends memories to
`CLAUDE.md` when `#` is pressed, so any drift from the canonical pointer means
instructions were written to the wrong file and must be moved into `AGENTS.md`.
"""

from __future__ import annotations

import argparse
import difflib
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

AGENTS_FILENAME = "AGENTS.md"
POINTER_FILENAME = "CLAUDE.md"

SKIP_DIRECTORIES = {
    ".git",
    ".next",
    ".venv",
    ".entire",
    "__pycache__",
    "build",
    "coverage",
    "dist",
    "node_modules",
    "out",
    "venv",
}

POINTER_TEMPLATE = """# CLAUDE.md

`AGENTS.md` is the single source of truth for agent instructions in this scope.
This file is a pointer only; it intentionally carries no instructions of its own.

Read and follow [AGENTS.md](./AGENTS.md).

<!--
Do not add content to this file, including memories captured by pressing `#`
in Claude Code. Put them in AGENTS.md instead. `make agent-docs-check` fails
when this pointer drifts.
-->
"""


def display_path(path: Path, root: Path) -> str:
    try:
        return str(path.relative_to(root))
    except ValueError:
        return str(path)


def normalize(text: str) -> list[str]:
    lines = [line.rstrip() for line in text.replace("\r\n", "\n").split("\n")]
    while lines and not lines[0]:
        lines.pop(0)
    while lines and not lines[-1]:
        lines.pop()
    return lines


def expected_lines() -> list[str]:
    return normalize(POINTER_TEMPLATE)


def find_agent_directories(root: Path) -> list[Path]:
    directories: set[Path] = set()

    for current_dir, dir_names, file_names in os.walk(root):
        dir_names[:] = [name for name in dir_names if name not in SKIP_DIRECTORIES]
        if AGENTS_FILENAME in file_names or POINTER_FILENAME in file_names:
            directories.add(Path(current_dir))

    return sorted(directories)


def added_lines(expected: list[str], actual: list[str]) -> list[str]:
    matcher = difflib.SequenceMatcher(a=expected, b=actual, autojunk=False)
    extras: list[str] = []
    for tag, _, _, actual_start, actual_end in matcher.get_opcodes():
        if tag in {"insert", "replace"}:
            extras.extend(line for line in actual[actual_start:actual_end] if line.strip())
    return extras


def check_pointer(pointer: Path, root: Path) -> list[str]:
    expected = expected_lines()
    actual = normalize(pointer.read_text(encoding="utf-8"))
    if actual == expected:
        return []

    name = display_path(pointer, root)
    agents_name = display_path(pointer.parent / AGENTS_FILENAME, root)
    errors = [
        f"{name} is not the canonical pointer to {agents_name}. "
        f"Move its instructions into {agents_name}, then restore the pointer "
        f"(`make agent-docs-check FIX=1`)."
    ]

    extras = added_lines(expected, actual)
    if extras:
        errors.append(f"{name} contains content that belongs in {agents_name}:")
        errors.extend(f"    {line}" for line in extras)

    return errors


def check_agent_docs(root: Path = ROOT) -> list[str]:
    errors: list[str] = []
    directories = find_agent_directories(root)

    if not (root / AGENTS_FILENAME).exists():
        errors.append(f"Missing {AGENTS_FILENAME} at the repository root.")

    for directory in directories:
        agents = directory / AGENTS_FILENAME
        pointer = directory / POINTER_FILENAME

        if not agents.exists():
            errors.append(
                f"{display_path(pointer, root)} has no sibling {AGENTS_FILENAME}. "
                f"Agent instructions live in {AGENTS_FILENAME}; add it or remove the pointer."
            )
            continue

        if not pointer.exists():
            errors.append(
                f"Missing {display_path(pointer, root)} next to {display_path(agents, root)}. "
                f"Run `make agent-docs-check FIX=1` to create the pointer."
            )
            continue

        errors.extend(check_pointer(pointer, root))

    return errors


def fix_agent_docs(root: Path = ROOT) -> tuple[list[str], list[str]]:
    """Restore canonical pointers, returning (changed paths, rescued content lines)."""
    changed: list[str] = []
    rescued: list[str] = []
    expected = expected_lines()

    for directory in find_agent_directories(root):
        agents = directory / AGENTS_FILENAME
        pointer = directory / POINTER_FILENAME
        if not agents.exists():
            continue

        if pointer.exists():
            actual = normalize(pointer.read_text(encoding="utf-8"))
            if actual == expected:
                continue
            extras = added_lines(expected, actual)
            if extras:
                rescued.append(f"# From {display_path(pointer, root)}:")
                rescued.extend(extras)

        pointer.write_text(POINTER_TEMPLATE, encoding="utf-8")
        changed.append(display_path(pointer, root))

    return changed, rescued


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--fix",
        action="store_true",
        help="Rewrite drifted CLAUDE.md pointers and print the content to move into AGENTS.md",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    if args.fix:
        changed, rescued = fix_agent_docs()
        if rescued:
            print("Move the following content into the matching AGENTS.md:\n")
            for line in rescued:
                print(f"  {line}")
            print()
        if changed:
            for name in changed:
                print(f"Restored canonical pointer: {name}")
            return 1 if rescued else 0
        print("Agent doc pointers already canonical.")
        return 0

    errors = check_agent_docs()
    if errors:
        print("Agent doc validation failed:")
        for error in errors:
            print(f"  - {error}")
        print(
            "\nAGENTS.md is the source of truth. CLAUDE.md must stay a pointer to it, "
            "so memories captured with `#` in Claude Code have to be moved into AGENTS.md."
        )
        return 1

    print("Agent doc validation passed.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

